        let config2 = config1.clone();

        assert_eq!(config1.rows, config2.rows);
        assert_eq!(config1.cols, config2.cols);
        assert_eq!(config1.shell, config2.shell);
        assert_eq!(config1.working_dir, config2.working_dir);
