// WebSocket test client simulator
// As specified in test-strategy-phase1.md §6.2

use anyhow::Result;
use tokio::net::TcpStream;
use tokio_tungstenite::{
    connect_async,
    tungstenite::Message,
    MaybeTlsStream,
    WebSocketStream,
};

/// Test WebSocket client for integration tests
pub struct TestWsClient {
    stream: Option<WebSocketStream<MaybeTlsStream<TcpStream>>>,
    url: String,
}

impl TestWsClient {
    /// Create a new test client (not yet connected)
    pub fn new(url: impl Into<String>) -> Self {
        Self {
            stream: None,
            url: url.into(),
        }
    }

    /// Connect to the WebSocket server
    pub async fn connect(&mut self) -> Result<()> {
        let (stream, _response) = connect_async(&self.url).await?;
        self.stream = Some(stream);
        Ok(())
    }

    /// Send a binary message
    pub async fn send_binary(&mut self, data: Vec<u8>) -> Result<()> {
        if let Some(ref mut stream) = self.stream {
            use futures_util::SinkExt;
            stream.send(Message::Binary(data)).await?;
            Ok(())
        } else {
            Err(anyhow::anyhow!("Not connected"))
        }
    }

    /// Receive a message
    pub async fn recv(&mut self) -> Result<Message> {
        if let Some(ref mut stream) = self.stream {
            use futures_util::StreamExt;
            let msg = stream
                .next()
                .await
                .ok_or_else(|| anyhow::anyhow!("Stream closed"))??;
            Ok(msg)
        } else {
            Err(anyhow::anyhow!("Not connected"))
        }
    }

    /// Close the connection
    pub async fn close(&mut self) -> Result<()> {
        if let Some(mut stream) = self.stream.take() {
            use futures_util::SinkExt;
            stream.close(None).await?;
        }
        Ok(())
    }

    /// Check if connected
    pub fn is_connected(&self) -> bool {
        self.stream.is_some()
    }
}

// TODO: Add helper methods once protocol is implemented:
// - send_attach_request()
// - send_input_data()
// - recv_output_data()
// - recv_attach_response()

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_client_creation() {
        let client = TestWsClient::new("ws://127.0.0.1:8080");
        assert!(!client.is_connected());
    }

    // More tests will be added once WebSocket server is implemented
}

